use vstd::prelude::*;

verus! {

spec fn rev_seq(s: Seq<i8>) -> Seq<i8> {
    s.reverse()
}

fn reverse(s: Vec<i8>) -> (rev: Vec<i8>)
    ensures
        rev@ == rev_seq(s@),
        rev@.len() == s@.len(),
{
    let n = s.len();
    let mut rev: Vec<i8> = Vec::with_capacity(n);

    for i in (0..n).rev()
        invariant
            n == s@.len(),
            rev@.len() <= n,
            // rev is exactly the reverse of the suffix s[i+1 .. n)
            rev@ == s@.subrange((i + 1) as int, n as int).reverse(),
        decreases
            i,
    {
        // Establish that indexing is in-bounds
        assert(i < s@.len());

        rev.push(s[i]);

        // After pushing s[i], rev becomes reverse of s[i .. n)
        assert(rev@ == s@.subrange(i as int, n as int).reverse());
    }

    // Loop ends with i == 0 processed; rev is reverse of s[0 .. n) == s
    assert(rev@ == s@.subrange(0, n as int).reverse());
    assert(s@.subrange(0, n as int) == s@);

    rev
}

} // verus!

